-- Integrity rules that schema.prisma cannot express: CHECK constraints and the
-- settings singletons. Written by hand for MariaDB 10.11+ (Hostinger); it is the
-- MariaDB counterpart of the PostgreSQL migration in
-- prisma/postgresql/migrations/20261120194038_integrity_rules. Prisma's schema
-- diff ignores CHECK constraints, so later migrations generated by
-- `prisma migrate dev` never drop them.
--
-- MariaDB differences, handled here and elsewhere:
--   * Text comparisons use the case-insensitive collation utf8mb4_unicode_ci,
--     so patterns that must be case-sensitive (slugs, hex hashes, lowercase
--     email) use the PCRE flag (?-i) or a comparison of the BINARY values.
--   * NO TRIGGERS in this migration. On shared hosting the database user has no
--     SUPER privilege and binary logging is usually on, and then MariaDB refuses
--     CREATE TRIGGER (error 1419). The PostgreSQL triggers are therefore split:
--       - slug history and status history are written by the application in the
--         same transaction (src/server/articles/history.ts);
--       - the guards (append-only activity_log, no deleting the Admin or the
--         singletons, section kinds, DB time on activity_log) are enforced by
--         the database client for every query (src/server/db/guards.ts), and
--         ALSO installed as triggers by `npm run db:migrate` when the host
--         allows it (prisma/sql/guard-triggers.sql);
--       - a separate runtime user without UPDATE/DELETE/DROP on activity_log
--         (scripts/db/grants.ts) when the host allows a second user.
--   * CHECK violations are MariaDB error 4025.
--
-- Privileges for the runtime user are NOT set here (user names differ per
-- environment): see scripts/db/grants.ts, run after every migration.

-- Every timestamp in this database is UTC (DATETIME has no time zone).
SET time_zone = '+00:00';

-- ─── 1. Exactly one Admin ────────────────────────────────────────────────────
-- id defaults to 1 and is the primary key, and this CHECK forbids any other
-- value: a second Admin row is impossible (PK conflict on 1, CHECK on others).
ALTER TABLE `admin_user`
  ADD CONSTRAINT `admin_user_single_admin` CHECK (`id` = 1),
  ADD CONSTRAINT `admin_user_email_format` CHECK (
    CAST(`email` AS BINARY) = CAST(LOWER(`email`) AS BINARY)
    AND CHAR_LENGTH(`email`) <= 254
    AND `email` REGEXP '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$'
  ),
  ADD CONSTRAINT `admin_user_name_not_blank` CHECK (TRIM(`name`) <> ''),
  ADD CONSTRAINT `admin_user_password_hash_scrypt` CHECK (CAST(`password_hash` AS BINARY) LIKE 'scrypt$%'),
  ADD CONSTRAINT `admin_user_failed_login_count_nonnegative` CHECK (`failed_login_count` >= 0),
  COMMENT = 'The single Admin account. id is always 1 (CHECK admin_user_single_admin). Created only by scripts/admin/bootstrap.ts.';

-- ─── 2. Sessions: 8 hours from the last activity at most ─────────────────────
ALTER TABLE `admin_session`
  ADD CONSTRAINT `admin_session_token_hash_sha256` CHECK (`token_hash` REGEXP '(?-i)^[0-9a-f]{64}$'),
  ADD CONSTRAINT `admin_session_timeline` CHECK (`last_seen_at` >= `created_at` AND `expires_at` > `last_seen_at`),
  ADD CONSTRAINT `admin_session_max_8_hours` CHECK (`expires_at` <= `last_seen_at` + INTERVAL 8 HOUR);

ALTER TABLE `login_attempt`
  ADD CONSTRAINT `login_attempt_reason_known` CHECK (
    CAST(`reason` AS BINARY) IN ('ok', 'bad_credentials', 'locked', 'rate_limited', 'invalid_input')
  ),
  ADD CONSTRAINT `login_attempt_success_matches_reason` CHECK (`success` = (CAST(`reason` AS BINARY) = 'ok'));

-- ─── 3. Editorial data ───────────────────────────────────────────────────────
ALTER TABLE `section`
  ADD CONSTRAINT `section_slug_format` CHECK (`slug` REGEXP '(?-i)^[a-z0-9]+(-[a-z0-9]+)*$' AND CHAR_LENGTH(`slug`) <= 80),
  ADD CONSTRAINT `section_name_not_blank` CHECK (TRIM(`name`) <> '');

ALTER TABLE `author`
  ADD CONSTRAINT `author_slug_format` CHECK (`slug` REGEXP '(?-i)^[a-z0-9]+(-[a-z0-9]+)*$' AND CHAR_LENGTH(`slug`) <= 80),
  ADD CONSTRAINT `author_name_not_blank` CHECK (TRIM(`name`) <> '');

ALTER TABLE `article`
  ADD CONSTRAINT `article_slug_format` CHECK (`slug` REGEXP '(?-i)^[a-z0-9]+(-[a-z0-9]+)*$' AND CHAR_LENGTH(`slug`) <= 120),
  ADD CONSTRAINT `article_title_not_blank` CHECK (TRIM(`title`) <> ''),
  -- PostgreSQL: tags text[] NOT NULL. MariaDB: a JSON array (of strings, enforced by the app).
  ADD CONSTRAINT `article_tags_array` CHECK (JSON_TYPE(`tags`) = 'ARRAY'),
  ADD CONSTRAINT `article_version_positive` CHECK (`version` >= 1),
  ADD CONSTRAINT `article_reading_minutes_positive` CHECK (`reading_minutes` >= 1),
  ADD CONSTRAINT `article_canonical_url_https` CHECK (`canonical_url` IS NULL OR `canonical_url` REGEXP '(?-i)^https://'),
  ADD CONSTRAINT `article_published_needs_date` CHECK (`status` <> 'PUBLISHED' OR `published_at` IS NOT NULL),
  ADD CONSTRAINT `article_published_needs_hero` CHECK (`status` <> 'PUBLISHED' OR `hero_media_id` IS NOT NULL),
  ADD CONSTRAINT `article_published_needs_section` CHECK (
    `status` <> 'PUBLISHED' OR `kanal_id` IS NOT NULL OR `rubrik_id` IS NOT NULL
  ),
  ADD CONSTRAINT `article_archived_needs_date` CHECK (`status` <> 'ARCHIVED' OR `archived_at` IS NOT NULL);

ALTER TABLE `article_slug_history`
  ADD CONSTRAINT `article_slug_history_slug_format` CHECK (`slug` REGEXP '(?-i)^[a-z0-9]+(-[a-z0-9]+)*$');

ALTER TABLE `article_revision`
  ADD CONSTRAINT `article_revision_version_positive` CHECK (`version` >= 1);

ALTER TABLE `article_media`
  ADD CONSTRAINT `article_media_position_nonnegative` CHECK (`position` >= 0);

-- ─── 4. Media ────────────────────────────────────────────────────────────────
ALTER TABLE `media`
  ADD CONSTRAINT `media_sha256_hex` CHECK (`sha256` REGEXP '(?-i)^[0-9a-f]{64}$'),
  ADD CONSTRAINT `media_size_positive` CHECK (`size_bytes` > 0),
  ADD CONSTRAINT `media_dimensions_positive` CHECK (
    (`width` IS NULL OR `width` > 0) AND (`height` IS NULL OR `height` > 0)
  ),
  ADD CONSTRAINT `media_variants_array` CHECK (JSON_TYPE(`variants`) = 'ARRAY');

ALTER TABLE `media_folder`
  ADD CONSTRAINT `media_folder_name_not_blank` CHECK (TRIM(`name`) <> '');

-- ─── 5. Homepage & site settings (singletons) ────────────────────────────────
ALTER TABLE `homepage_settings`
  ADD CONSTRAINT `homepage_settings_singleton` CHECK (`id` = 1),
  ADD CONSTRAINT `homepage_settings_latest_count_range` CHECK (`latest_count` BETWEEN 1 AND 24);

ALTER TABLE `homepage_featured`
  ADD CONSTRAINT `homepage_featured_position_range` CHECK (`position` BETWEEN 0 AND 11);

ALTER TABLE `homepage_rubric`
  ADD CONSTRAINT `homepage_rubric_position_range` CHECK (`position` BETWEEN 0 AND 5),
  ADD CONSTRAINT `homepage_rubric_item_count_range` CHECK (`item_count` BETWEEN 1 AND 12);

ALTER TABLE `site_settings`
  ADD CONSTRAINT `site_settings_singleton` CHECK (`id` = 1),
  ADD CONSTRAINT `site_settings_social_links_object` CHECK (JSON_TYPE(`social_links`) = 'OBJECT');

-- The singleton rows always exist, so the app never has to create them.
INSERT INTO `homepage_settings` (`id`, `latest_count`, `updated_at`) VALUES (1, 4, CURRENT_TIMESTAMP(3))
  ON DUPLICATE KEY UPDATE `id` = `id`;
INSERT INTO `site_settings` (`id`, `social_links`, `updated_at`) VALUES (1, '{}', CURRENT_TIMESTAMP(3))
  ON DUPLICATE KEY UPDATE `id` = `id`;

-- ─── 6. Activity Log: append-only ────────────────────────────────────────────
ALTER TABLE `activity_log`
  ADD CONSTRAINT `activity_log_action_format` CHECK (`action` REGEXP '(?-i)^[a-z][a-z_]*([.][a-z][a-z_]*)+$'),
  ADD CONSTRAINT `activity_log_admin_actor_has_admin` CHECK (`actor` <> 'ADMIN' OR `admin_id` IS NOT NULL),
  ADD CONSTRAINT `activity_log_meta_object` CHECK (JSON_TYPE(`meta`) = 'OBJECT'),
  COMMENT = 'Append-only audit trail. UPDATE/DELETE are rejected by triggers; the runtime user has no UPDATE/DELETE/DROP privilege.';

